import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, mix, time, vec3, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const root = new Group();

  // Plane geometry (7x6 units, high tessellation)
  const geometry = new PlaneGeometry(7, 6, 64, 64);
  const material = new MeshStandardNodeMaterial({
    color: config.intent?.visualSpec?.colors?.paper || '#e8ecf2',
    metalness: 0.5,
    roughness: 0.6,
    clearcoat: 0.2,
    transparent: true,
  });

  const plane = new Mesh(geometry, material);
  plane.position.z = -2.5; // backdrop depth per spec
  root.add(plane);

  // Load textures asynchronously; material will update when ready
  const imagePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const depthPromise = ctx.textureLoader.loadTexture(config.depthMapUrl);
  Promise.all([imagePromise, depthPromise]).then(([imgTex, depthTex]) => {
    material.map = imgTex;
    material.displacementMap = depthTex;
    material.displacementScale = 0.2;
    material.needsUpdate = true;
  });

  // Apply cinematic primitives defined in config
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (fn) {
        const instance = fn(root, prim.params || {});
        primitiveInstances.push(instance);
      }
    }
  }

  // Event handlers (hover, click)
  root.userData.handlers = {};

  // Hover rise‑in effect (subtle +0.15 units)
  root.userData.handlers.hover = () => {
    const tl = gsap.timeline();
    tl.to(root.position, { y: root.position.y + 0.15, duration: 0.3, ease: 'power3.out' });
    root.userData._hoverTL = tl;
  };
  // Optional unhover to return to original position
  root.userData.handlers.unhover = () => {
    if (root.userData._hoverTL) root.userData._hoverTL.kill();
    const tl = gsap.timeline();
    tl.to(root.position, { y: root.position.y - 0.15, duration: 0.2, ease: 'power3.in' });
  };

  // Click emits navigation event
  root.userData.handlers.click = () => {
    ctx.emit('hub-home.select', {});
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose material & geometry
    material.dispose();
    geometry.dispose();

    // Kill any GSAP timelines
    if (root.userData._hoverTL) root.userData._hoverTL.kill();

    // Cleanup primitives
    for (const p of primitiveInstances) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }
  };

  return root;
}
